fn find_first_odd(a: &[i32]) -> (bool, usize) {
    // Use Iterator::position to find the first index where the element is odd.
    // `position` returns `Some(index)` if an element satisfies the predicate,
    // or `None` otherwise.
    match a.iter().position(|&x| x % 2 != 0) {
        Some(idx) => (true, idx),
        None => (false, 0),
    }
}

